import Domain
import SwiftUI

// MARK: - Sidebar ("Sections Rail")

@MainActor
public struct BroadsheetSidebarView: View {
    @Environment(BroadsheetAppState.self) private var appState

    public init() {}

    public var body: some View {
        @Bindable var appState = appState
        VStack(spacing: 0) {
            HStack {
                Image(systemName: "magnifyingglass")
                    .foregroundStyle(Color.ink3)
                    .font(Typography.uiSmall)
                TextField("Search", text: $appState.searchQuery)
                    .font(Typography.uiLabel)
                    .textFieldStyle(.plain)
            }
            .padding(.horizontal, Metrics.unit)
            .padding(.vertical, Metrics.unit * 0.75)
            .background(Color.tint)
            .overlay(Rectangle().stroke(Color.hairlineColor, lineWidth: Metrics.hairline))
            .padding(Metrics.unit)

            if appState.isRecording {
                OnTheWireCard()
            }

            List {
                Section {
                    SidebarRow(item: .inbox, label: "Inbox", count: nil)
                    SidebarRow(item: .pinned, label: "Pinned", count: nil)
                    SidebarRow(item: .recurring, label: "Recurring", count: nil)
                    SidebarRow(item: .allMeetings, label: "All Meetings", count: nil)
                } header: {
                    SidebarSectionHeader(title: "MEETINGS")
                }
            }
            .scrollContentBackground(.hidden)
            .background(Color.newsprint)
            .listStyle(.plain)
        }
        .background(Color.newsprint)
    }
}

// MARK: - On The Wire Card

@MainActor
struct OnTheWireCard: View {
    @Environment(BroadsheetAppState.self) private var appState
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var pulsing = false

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack(spacing: 6) {
                Circle()
                    .fill(Color.breaking)
                    .frame(width: 6, height: 6)
                    .opacity(reduceMotion ? 1 : (pulsing ? 1 : 0.3))
                    .animation(reduceMotion ? nil : .easeInOut(duration: 0.8).repeatForever(), value: pulsing)
                    .onAppear { if !reduceMotion { pulsing = true } }
                    .accessibilityLabel("Recording in progress")
                Text("ON THE WIRE").kicker()
            }
            Text(appState.recordingUIState == .recording ? "Recording live" : "Processing…")
                .font(Typography.uiLabel)
                .foregroundStyle(Color.ink)
        }
        .padding(Metrics.unit)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color.tint)
        .overlay(Rectangle().stroke(Color.breaking.opacity(0.3), lineWidth: Metrics.hairline))
        .padding(.horizontal, Metrics.unit)
        .padding(.bottom, Metrics.unit)
    }
}

// MARK: - Sidebar Section Header

@MainActor
struct SidebarSectionHeader: View {
    let title: String

    var body: some View {
        VStack(spacing: 0) {
            Rectangle().fill(Color.hairlineColor).frame(height: Metrics.hairline)
            HStack {
                Text(title).kicker()
                Spacer()
            }
            .padding(.horizontal, Metrics.unit)
            .padding(.vertical, 4)
        }
        .background(Color.newsprint)
    }
}

// MARK: - Sidebar Row

@MainActor
struct SidebarRow: View {
    let item: BroadsheetSidebarItem
    let label: String
    let count: Int?
    @Environment(BroadsheetAppState.self) private var appState

    private var isSelected: Bool {
        appState.selectedSidebarItem == item
    }

    var body: some View {
        Button {
            appState.selectedSidebarItem = item
        } label: {
            HStack {
                Text(label)
                    .font(Typography.uiLabel)
                    .foregroundStyle(isSelected ? Color.ink : Color.ink2)
                Spacer()
                if let count {
                    Text("\(count)").font(Typography.uiSmall).foregroundStyle(Color.ink3)
                }
            }
            .padding(.horizontal, Metrics.unit)
            .padding(.vertical, 6)
            .background(alignment: .leading) {
                if isSelected {
                    Rectangle().fill(Color.rule).frame(width: 2)
                }
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .listRowBackground(isSelected ? Color.highlight.opacity(0.3) : Color.clear)
        .accessibilityLabel(label)
        .accessibilityAddTraits(isSelected ? .isSelected : [])
    }
}

