@Suite("BroadsheetAppState sidebar search (#256)")
@MainActor
struct BroadsheetAppStateSearchTests {
    @Test("empty query shows all meetings")
    func emptyQueryShowsAll() {
        let state = makeBroadsheetAppState()
        state.libraryVM.meetings = [
            makeMetadata(id: RecordingID("rec-1"), wordCount: 10),
            makeMetadata(id: RecordingID("rec-2"), wordCount: 777),
        ]

        state.searchQuery = ""

        #expect(state.displayedMeetings.count == 2)
    }

    @Test("query filters displayedMeetings to matching meetings only")
    func queryFiltersDisplayedMeetings() {
        let state = makeBroadsheetAppState()
        state.libraryVM.meetings = [
            makeMetadata(id: RecordingID("rec-1"), wordCount: 10),
            makeMetadata(id: RecordingID("rec-2"), wordCount: 777),
        ]

        // "777" only appears in the second meeting's deck ("777 words").
        state.searchQuery = "777"

        #expect(state.displayedMeetings.count == 1)
        #expect(state.displayedMeetings.first?.id == RecordingID("rec-2"))
    }

    @Test("query matching is case-insensitive")
    func queryIsCaseInsensitive() {
        let state = makeBroadsheetAppState()
        state.libraryVM.meetings = [makeMetadata(id: RecordingID("rec-1"), wordCount: 10)]

