    @Test("setting searchQuery recomputes groupedDisplayedMeetings")
    func settingQueryRecomputesGroups() {
        let state = makeBroadsheetAppState()
        state.libraryVM.meetings = [
            makeMetadata(id: RecordingID("rec-1"), wordCount: 10),
            makeMetadata(id: RecordingID("rec-2"), wordCount: 777),
        ]
        state.recomputeGroupedMeetings()
        #expect(state.groupedDisplayedMeetings.flatMap(\.meetings).count == 2)

        state.searchQuery = "777"

        let grouped = state.groupedDisplayedMeetings.flatMap(\.meetings)
        #expect(grouped.count == 1)
        #expect(grouped.first?.id == RecordingID("rec-2"))
    }

    @Test("clearing the query restores the full list")
    func clearingQueryRestoresAll() {
        let state = makeBroadsheetAppState()
        state.libraryVM.meetings = [
            makeMetadata(id: RecordingID("rec-1"), wordCount: 10),
            makeMetadata(id: RecordingID("rec-2"), wordCount: 777),
        ]

        state.searchQuery = "777"
        #expect(state.displayedMeetings.count == 1)

        state.searchQuery = ""
        #expect(state.displayedMeetings.count == 2)
    }
}

import Foundation
import Logging
import Domain

/// Orchestrates stopping an active audio capture session, persisting the
/// resulting file, and transcribing the recorded audio in a single operation.
///
/// All external I/O is delegated to injected domain protocols so this actor
/// contains no direct file-system or audio-framework dependencies.
public actor StopAndTranscribeUseCase {

    // MARK: - Dependencies

    private let audioCapture: any AudioCaptureEngine
    private let transcription: any TranscriptionEngine
    private let storage: any RecordingWriteRepository & TranscriptWriteRepository
    private let sampleLoader: any AudioSampleLoader
    private let telemetry: (any InferenceMetricsRecorder)?

    // MARK: - Configuration

    private let modelId: ModelID

    // MARK: - Logging

    private let logger = AppLogger.for(category: "Transcription")

    // MARK: - Init

    public init(
        audioCapture: any AudioCaptureEngine,
        transcription: any TranscriptionEngine,
        storage: any RecordingWriteRepository & TranscriptWriteRepository,
        sampleLoader: any AudioSampleLoader,
        modelId: ModelID,
        telemetry: (any InferenceMetricsRecorder)? = nil,
    ) {
        self.audioCapture = audioCapture
        self.transcription = transcription
        self.storage = storage
        self.sampleLoader = sampleLoader
        self.modelId = modelId
        self.telemetry = telemetry
    }

    // MARK: - Execute

    /// Stops the active recording session, persists the audio file, and
    /// transcribes the captured audio.
    ///
    /// - Parameter session: The active ``RecordingSession`` to finalise.
    /// - Returns: A ``TranscribedRecording`` containing the stored file and its
    ///   transcription result.
    /// - Throws: Any error produced by the audio capture, storage, or
    ///   transcription engines — errors are never swallowed here.
    public func stopAndTranscribe(session: RecordingSession) async throws -> TranscribedRecording {
        logger.info("Stopping recording for session \(session.id, privacy: .public)")

        do {
            // 1. Stop capture — produces the completed audio file.
            try Task.checkCancellation()
            let audioFile = try await audioCapture.stop()
            logger.info("Audio capture stopped; file: \(audioFile.url.lastPathComponent, privacy: .public)")

            // 1.b Transactionally verify file presence (TOCTOU fix).
            // Opening the file for reading will throw immediately if the file
            // was deleted or is unreadable, preventing us from saving a stub
            // record into the database that we can't actually transcribe.
            let handle = try FileHandle(forReadingFrom: audioFile.url)
            defer { try? handle.close() }

            // Check for cancellation before attempting persistence. If cancelled
            // here, delete the WAV — nothing is in the database yet so there is
            // nothing to retry. On any other (storage) failure the WAV is kept
            // so the caller can retry.
            do {
                try Task.checkCancellation()
            } catch {
                try? FileManager.default.removeItem(at: audioFile.url)
                logger
                    .info(
                        "Cleaned up temporary audio file after cancellation: \(audioFile.url.lastPathComponent, privacy: .public)",
                    )
                throw error
            }

            // 2. Persist the audio file.
            // If saveRecording throws (transient DB error), the WAV is intentionally
            // preserved on disk so the caller can surface a retryable error to the UI.
            let storedRecording = try await storage.saveRecording(audioFile)
            logger.info("Recording saved; id: \(storedRecording.metadata.id, privacy: .public)")

            // 3–9. Load samples, transcribe, record telemetry, persist transcript.
            try Task.checkCancellation()
            do {
                let result = try await transcribeAndPersist(
                    audioFile: audioFile,
                    session: session,
                    storedRecording: storedRecording
                )
                // 10. Return the paired recording + transcription.
                return TranscribedRecording(recording: storedRecording, transcription: result)
            } catch {
                // AC-2 / AC-4 (#116): On transcription failure, mark the recording as
                // needing re-transcription so it can be retried on next launch —
                // but only if the WAV file has non-zero size (AC-4 integrity gate).
                if audioFile.fileSize > 0 {
                    do {
                        try await storage.markNeedsRetranscription(
                            id: storedRecording.metadata.id,
                            audioURL: audioFile.url
                        )
                    } catch {
                        logger.error("Failed to mark recording for retry — may be orphaned: \(error, privacy: .private)")
                    }
                }
                throw error
            }
        } catch {
            logger.error("StopAndTranscribe failed: \(error, privacy: .private)")
            throw error
        }
    }

    // MARK: - Private helpers

    private func transcribeAndPersist(
        audioFile: AudioFile,
        session: RecordingSession,
        storedRecording: StoredRecording,
    ) async throws -> TranscriptionResult {
        async let samples = sampleLoader.loadSamples(from: audioFile.url)
        async let ready = transcription.isReady()
        let (loadedSamples, isReady) = try await (samples, ready)

        let context = TranscriptionContext(
            modelId: modelId, sessionId: session.id, isFinalChunk: true, timestampOffset: 0,
        )
        if !isReady { try await transcription.loadModel(modelId) }

        try Task.checkCancellation()
        let clock = ContinuousClock()
        let start = clock.now
        let segment = try await transcription.transcribe(samples: loadedSamples, context: context)
        let computeUnit = await transcription.getComputeUnit()
        let duration = start.duration(to: clock.now)
        let elapsed = Double(duration.components.seconds)
            + Double(duration.components.attoseconds) / 1_000_000_000_000_000_000

        logger.info("Transcription complete in \(String(format: "%.3f", elapsed), privacy: .public)s")
        let audioDuration = Double(loadedSamples.count) / 16000.0
        await telemetry?.record(InferenceMetrics(
            modelId: modelId, audioDuration: audioDuration, inferenceDuration: elapsed,
            realTimeFactor: elapsed > 0 ? audioDuration / elapsed : 0,
            confidence: segment.confidence, sampleCount: loadedSamples.count,
            computeUnit: computeUnit, timestamp: Date(),
        ))

        let result = TranscriptionResult(
            segments: [segment], fullText: segment.text, processingTime: elapsed,
            modelId: modelId, recordedAt: Date(), computeUnit: computeUnit, passType: .live,
        )
        try Task.checkCancellation()
        try await storage.updateTranscript(id: storedRecording.metadata.id, transcript: result)
        logger.info("Live transcript persisted for recording \(storedRecording.metadata.id, privacy: .public)")
        return result
    }

    // MARK: - BM-047: Force-stop (best-effort; errors swallowed)

    /// Attempts to stop the audio capture engine without propagating errors.
    ///
    /// Called by `MenuBarViewModel` from its error-path catch block to ensure
    /// the capture engine is always halted even when `execute()` throws.
    /// Errors are intentionally swallowed — force-stop failure must not mask
    /// the original error that brought us to the catch block.
    public func forceStop() async {
        do {
            let audioFile = try await audioCapture.stop()
            try? FileManager.default.removeItem(at: audioFile.url)
            // swiftlint:disable:next line_length
            logger
                .info(
                    "Force stop cleaned up temporary audio file: \(audioFile.url.lastPathComponent, privacy: .private)",
                )
        } catch {
            logger.warning("BM-047: force-stop capture failed (swallowed): \(error, privacy: .private)")
        }
    }
}

