import Domain
import Foundation
import Logging
import MLInfrastructure
import Presentation

/// Composition-root adapter for `IntegrationSettingsStore` (Presentation). Bridges the
/// Settings "Integrations" tab to the real Keychain, `ConfigManager`, and `NotionProvider`
/// pieces so Presentation never imports Infrastructure directly.
///
/// v1 scope: writes made through this adapter take effect on next launch — MCP providers
/// are constructed once at startup (`AppAssembler.buildMCPProviders`) and are not
/// hot-reloaded.
final class LiveIntegrationSettingsStore: IntegrationSettingsStore {
    private let configManager: ConfigManager
    private let credentialStore: any CredentialStore
    private let notionProviderID = "notion"
    private let logger = AppLogger.for(category: "LiveIntegrationSettingsStore")

    init(configManager: ConfigManager, credentialStore: any CredentialStore = KeychainCredentialStore()) {
        self.configManager = configManager
        self.credentialStore = credentialStore
    }

    func loadNotionEnabled() async -> Bool {
        do {
            return try await configManager.load().notionEnabled
        } catch {
            logger.error("Failed to load AppConfig while reading notionEnabled: \(String(reflecting: error), privacy: .private)")
            return false
        }
    }

    @discardableResult
    func setNotionEnabled(_ enabled: Bool) async -> Bool {
        await updateConfig { config in
            Self.replacing(config, notionEnabled: enabled, obsidianVaultBookmark: config.obsidianVaultBookmark)
        }
    }

    func loadNotionAPIKey() async -> String {
        do {
            return try credentialStore.credential(for: notionProviderID) ?? ""
        } catch {
            logger.error("Failed to read Notion API key from Keychain: \(String(reflecting: error), privacy: .private)")
            return ""
        }
    }

    @discardableResult
    func setNotionAPIKey(_ apiKey: String) async -> Bool {
        do {
            try credentialStore.store(credential: apiKey, for: notionProviderID)
            return true
        } catch {
            logger.error("Failed to store Notion API key in Keychain: \(String(reflecting: error), privacy: .private)")
            return false
        }
    }

    func loadObsidianVaultPath() async -> String {
        let bookmark: Data
        do {
            guard let stored = try await configManager.load().obsidianVaultBookmark else { return "" }
            bookmark = stored
        } catch {
            logger.error(
                "Failed to load AppConfig while reading Obsidian vault bookmark: \(String(reflecting: error), privacy: .private)"
            )
            return ""
        }
        var isStale = false
        let url: URL
        do {
            url = try URL(
                resolvingBookmarkData: bookmark,
                options: .withSecurityScope,
                relativeTo: nil,
                bookmarkDataIsStale: &isStale
            )
        } catch {
            logger.error("Failed to resolve Obsidian vault bookmark: \(String(reflecting: error), privacy: .private)")
            return ""
        }
        if isStale {
            logger.warning("Obsidian vault bookmark is stale; regenerating and persisting a fresh bookmark")
            await regenerateObsidianBookmark(for: url)
        }
        return url.path
    }

    @discardableResult
    func setObsidianVault(url: URL) async -> Bool {
        let bookmark: Data
        do {
            bookmark = try url.bookmarkData(
                options: .withSecurityScope,
                includingResourceValuesForKeys: nil,
                relativeTo: nil
            )
        } catch {
            logger.error(
                "Failed to create security-scoped bookmark for Obsidian vault: \(String(reflecting: error), privacy: .private)"
            )
            return false
        }
        return await updateConfig { config in
            Self.replacing(config, notionEnabled: config.notionEnabled, obsidianVaultBookmark: bookmark)
        }
    }

    @discardableResult
    func clearObsidianVault() async -> Bool {
        await updateConfig { config in
            Self.replacing(config, notionEnabled: config.notionEnabled, obsidianVaultBookmark: nil)
        }
    }

    /// Regenerates and persists a fresh security-scoped bookmark for `url` when the
    /// previously stored bookmark reported `bookmarkDataIsStale == true` (e.g. after a
    /// volume rename or app relocation). Without this, access keeps degrading further
    /// on every subsequent launch with no signal to the user. Brackets bookmark
    /// creation with the security scope per Apple's documented staleness-renewal
    /// pattern, then persists through the same `updateConfig` path `setObsidianVault`
    /// uses.
    private func regenerateObsidianBookmark(for url: URL) async {
        let didStartAccessing = url.startAccessingSecurityScopedResource()
        defer {
            if didStartAccessing { url.stopAccessingSecurityScopedResource() }
        }
        guard let freshBookmark = try? url.bookmarkData(
            options: .withSecurityScope,
            includingResourceValuesForKeys: nil,
            relativeTo: nil
        ) else {
            logger.warning("Failed to regenerate stale Obsidian vault bookmark")
