        await NotionProvider(credentialStore: credentialStore).isHealthy(apiKeyOverride: apiKey)
    }

    // MARK: - Helpers

    @discardableResult
    private func updateConfig(_ transform: (AppConfig) -> AppConfig) async -> Bool {
        let current: AppConfig
        do {
            current = try await configManager.load()
        } catch {
            let detail = String(reflecting: error)
            logger.error("Failed to load AppConfig before applying integration settings update: \(detail, privacy: .private)")
            return false
        }
        do {
            try await configManager.save(transform(current))
            return true
        } catch {
            logger.error(
                "Failed to save AppConfig after applying integration settings update: \(String(reflecting: error), privacy: .private)"
            )
            return false
        }
    }

    private static func replacing(
        _ config: AppConfig,
        notionEnabled: Bool,
        obsidianVaultBookmark: Data?
    ) -> AppConfig {
        AppConfig(
            summarization: config.summarization,
            transcription: config.transcription,
            storage: config.storage,
            translation: config.translation,
            contextCache: config.contextCache,
            audioCapture: config.audioCapture,
            uiTheme: config.uiTheme,
            privacyMode: config.privacyMode,
            mcpConsentGranted: config.mcpConsentGranted,
            mcpEndpoints: config.mcpEndpoints,
            notionEnabled: notionEnabled,
            obsidianVaultBookmark: obsidianVaultBookmark
        )
    }
}

